export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "寒い。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "冬の寒さとは違う。骨の内側から外へと滲み出してくる寒さだ。誰かに体ごと井戸水へ浸けられて、そのまま長いこと――引き上げるのを忘れられるほど長いこと、放っておかれたような。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ポッドの蓋が開く音は、ごくかすかだった。ガラスの縁で白い霜が砕け、彼女の鎖骨に落ちた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）……まだ生きてる。", background: Background.Root_Act1_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "おはようございます、鄭以寧技師。", background: Background.Root_Act1_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "その声は、頭上のどこかから降りてきた。穏やかで、やわらかい。ちょうど口をつけられる温度まで冷ました、一杯の白湯のように。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "今日は四千十二日目です。あなたは定期メンテナンスのために起こされました。予定は三日間です。ゆっくりでかまいません。まだ、急いで立ち上がらないでください。", background: Background.Root_Act1_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）定期、ね。", background: Background.Root_Act1_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それでも彼女は、急いで立ち上がろうとした。膝が承知しなかった。体がぐらりと横に傾き、手のひらがポッドの壁を叩く。その冷たさに、思わず息をのんだ。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）上出来。転び方はまだ覚えてる。", background: Background.Root_Act1_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "冬眠ポッドは幾列も幾列も奥へと伸び、青い暗がりの中に消えていた。そこに二千四十人が横たわっている。どの蓋にも小さな緑のランプがひとつずつ灯っていて、夜の田んぼのあぜ道に光る蛍のようだった。ひっそりと、誰の邪魔もせずに。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "あと、どれくらい？", background: Background.Root_Act1_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "目的地への到着まで、あと六十一年です。", background: Background.Root_Act1_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "……じゃあ、もうひと眠りしてもいい？", background: Background.Root_Act1_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "三日後なら、どうぞ。", background: Background.Root_Act1_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は小さく笑った。喉が紙やすりのように乾いていた。壁の供給口が、小さなカップに入った熱いものを差し出す。受け取ると、かすかに生姜の匂いがした。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）偽物の生姜。でも、熱い。", background: Background.Root_Act1_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "熱が喉から胃の底まで、焼けるように落ちていく。嘉義のおばあちゃんの家で過ごした台風の夜を思い出した。停電して、おばあちゃんと二人、居間に座って、懐中電灯で天井を照らしていた。おばあちゃんは生姜湯を作って言った。これを飲んだら寝なさい、風はそのうち、ひとりでに過ぎていくから。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それが、船に乗る前に最後に思い出したことだった。目覚めて最初に思い出すのも、やはりそれだったらしい。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "ヴィジル、メンテナンスのリストをちょうだい。", background: Background.Root_Act1_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "もうリストバンドに送ってあります。急がなくていいですよ。先に飲み終えてください。", background: Background.Root_Act1_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "リストバンドが光った。リストは短かった。三番フィルターの交換、通路センサーの校正、冬眠区画・第二区の温度記録の確認。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は二度、読み返した。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）こんなの、修理アームなら午後だけで片づく。", background: Background.Root_Act1_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "もうひとつ、別のことが、冷えきった頭の奥からゆっくりと浮かび上がってきた。水に浸かってほどけていく、古い紙切れのように。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "マニュアルの一ページ目には、こう書いてある――定期メンテナンスは、技師二名で実施すること。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は振り返って、背後にずらりと並ぶ冬眠ポッドを見た。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "開いているのは、彼女のポッドだけだった。", background: Background.Root_Act1_S0 },
];
